    if (box1.Max.Y < box2.Min.Y || box2.Max.Y < box1.Min.Y)
        return BoxRelation::Separated;
    if (box1.Max.Y == box2.Min.Y || box2.Max.Y == box1.Min.Y)
        touch = true;

    // Z axis
    if (box1.Max.Z < box2.Min.Z || box2.Max.Z < box1.Min.Z)
        return BoxRelation::Separated;
    if (box1.Max.Z == box2.Min.Z || box2.Max.Z == box1.Min.Z)
        touch = true;

    return touch ? BoxRelation::Adjacent : BoxRelation::Overlapped;
}

